import 'package:flutter/material.dart';import '../data/app_store.dart';import '../models/process_circuit.dart';import '../theme/operon_theme.dart';
class ProcessCircuitsScreen extends StatefulWidget{final AppStore store;const ProcessCircuitsScreen({super.key,required this.store});@override State<ProcessCircuitsScreen> createState()=>_S();}
class _S extends State<ProcessCircuitsScreen>{@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Process circuits')),body:widget.store.circuits.isEmpty?const Center(child:Text('No process circuits yet')):ListView(padding:const EdgeInsets.all(16),children:widget.store.circuits.map((x)=>Card(child:ListTile(onTap:()=>_view(x),leading:const Icon(Icons.account_tree,color:OperonTheme.teal),title:Text(x.name,style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text('${x.nodes.length} linked TAGs · ${x.pidReference.isEmpty?'No P&ID reference':x.pidReference}'),trailing:const Icon(Icons.chevron_right)))).toList()),floatingActionButton:FloatingActionButton.extended(onPressed:_add,icon:const Icon(Icons.add),label:const Text('Circuit')));
void _add(){final name=TextEditingController(),desc=TextEditingController(),pid=TextEditingController(),source=TextEditingController(),tags=TextEditingController();showModalBottomSheet(context:context,isScrollControlled:true,showDragHandle:true,builder:(c)=>Padding(padding:EdgeInsets.fromLTRB(20,0,20,MediaQuery.viewInsetsOf(c).bottom+30),child:ListView(shrinkWrap:true,children:[const Text('New process circuit',style:TextStyle(fontSize:24,fontWeight:FontWeight.w800)),const SizedBox(height:12),TextField(controller:name,decoration:const InputDecoration(labelText:'Circuit name')),const SizedBox(height:8),TextField(controller:desc,maxLines:3,decoration:const InputDecoration(labelText:'Description')),const SizedBox(height:8),TextField(controller:tags,maxLines:3,decoration:const InputDecoration(labelText:'TAG flow order',hintText:'V-2100, P-2101A, E-2204, FV-2205')),const SizedBox(height:8),TextField(controller:pid,decoration:const InputDecoration(labelText:'Approved P&ID reference')),const SizedBox(height:8),TextField(controller:source,decoration:const InputDecoration(labelText:'Source / owner')),const SizedBox(height:14),FilledButton(onPressed:(){final ns=tags.text.split(',').map((e)=>e.trim().toUpperCase()).where((e)=>e.isNotEmpty).toList();widget.store.saveCircuit(ProcessCircuit(id:DateTime.now().microsecondsSinceEpoch.toString(),name:name.text.trim().isEmpty?'Process circuit':name.text.trim(),description:desc.text.trim(),pidReference:pid.text.trim(),source:source.text.trim(),nodes:[for(var i=0;i<ns.length;i++)CircuitNode(tag:ns[i],role:i==0?'upstream':i==ns.length-1?'downstream':'process',order:i)]));Navigator.pop(c);setState((){});},child:const Text('Save circuit'))])));}
void _view(ProcessCircuit x)=>showModalBottomSheet(context:context,isScrollControlled:true,showDragHandle:true,builder:(c)=>DraggableScrollableSheet(expand:false,initialChildSize:.72,maxChildSize:.94,builder:(_,scroll)=>ListView(controller:scroll,padding:const EdgeInsets.fromLTRB(20,0,20,40),children:[Text(x.name,style:const TextStyle(fontSize:26,fontWeight:FontWeight.w800)),if(x.description.isNotEmpty)Padding(padding:const EdgeInsets.only(top:6),child:Text(x.description,style:const TextStyle(color:OperonTheme.muted))),if(x.pidReference.isNotEmpty)ListTile(contentPadding:EdgeInsets.zero,leading:const Icon(Icons.description,color:OperonTheme.teal),title:Text(x.pidReference),subtitle:Text(x.source.isEmpty?'Approved reference required':x.source)),const SizedBox(height:10),...x.nodes.asMap().entries.map((e)=>Row(crossAxisAlignment:CrossAxisAlignment.start,children:[SizedBox(width:38,child:Column(children:[CircleAvatar(radius:14,child:Text('${e.key+1}',style:const TextStyle(fontSize:11))),if(e.key<x.nodes.length-1)Container(width:2,height:38,color:OperonTheme.teal)])),Expanded(child:Card(child:ListTile(title:Text(e.value.tag,style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text(e.value.role))))]))])));}
